sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float chroma;
uniform float smear;
uniform float scanlines;
uniform float noise;
uniform float tracking;
uniform float wobble;
uniform float saturation;
uniform float headSwitch;
uniform float seed;

float hash(float2 p) {
    p = fract(p * float2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return fract(p.x * p.y);
}

float wave(float x, float s) {
    float i = floor(x);
    float f = fract(x);
    return mix(hash(float2(i, s)), hash(float2(i + 1.0, s)), f * f * (3.0 - 2.0 * f));
}

float3 toYiq(float3 c) {
    return float3(dot(c, float3(0.299, 0.587, 0.114)), dot(c, float3(0.596, -0.274, -0.322)), dot(c, float3(0.211, -0.523, 0.312)));
}

float3 toRgb(float3 c) {
    return float3(dot(c, float3(1.0, 0.956, 0.621)), dot(c, float3(1.0, -0.272, -0.647)), dot(c, float3(1.0, -1.106, 1.703)));
}

float3 plain(half4 c) {
    return c.a > 0.0 ? float3(c.rgb) / float(c.a) : float3(0.0);
}

half4 main(float2 coord) {
    float frame = mod(floor(time * 30.0), 997.0);
    float s = mod(seed, 1000.0) * 0.731 + 0.17;
    float y = coord.y;
    float line = mod(floor(y), 2048.0);
    float shift = (hash(float2(line * 0.37 + s, frame)) - 0.5) * wobble * 0.6 + (wave(y * 0.015 + time * 1.7, s + 3.0) - 0.5) * wobble * 2.0;
    float roll = fract(time * 0.09 + hash(float2(s, 7.0))) * size.y * 1.4 - size.y * 0.2;
    float reach = size.y * 0.05 + 4.0;
    float band = smoothstep(reach, 0.0, abs(y - roll)) * tracking * smoothstep(0.3, 0.6, wave(time * 0.4, s + 11.0));
    shift += band * (hash(float2(line, frame + 1.0)) - 0.3) * 28.0;
    float head = headSwitch > 0.5 ? smoothstep(size.y * 0.035 + 3.0, 0.0, size.y - y) : 0.0;
    shift += head * (10.0 + 16.0 * hash(float2(floor(y * 0.5), frame + 2.0)));
    float2 p = float2(coord.x - shift, y);
    half4 base = image.eval(p);
    half4 smeared = base;
    for (int i = 1; i <= 4; i++) {
        smeared += image.eval(p - float2(smear * float(i) * 0.5, 0.0));
    }
    smeared *= 0.2;
    half4 bleed = half4(0.0);
    for (int i = 0; i < 4; i++) {
        bleed += image.eval(p - float2(chroma * (0.6 + 0.4 * float(i)), 0.0));
    }
    bleed *= 0.25;
    half alpha = max(base.a, max(smeared.a, bleed.a));
    if (alpha <= 0.0) return half4(0.0);
    float luma = toYiq(mix(plain(base), plain(smeared), 0.7)).x;
    float2 iq = toYiq(plain(bleed)).yz * saturation;
    float grain = hash(float2(coord.x * 0.71 + frame * 3.1, y * 1.3 + s)) - 0.5;
    luma += grain * noise * 0.22;
    float streak = step(1.0 - noise * 0.004 - band * 0.2, hash(float2(floor(coord.x / 24.0) + line * 0.13, frame + s)));
    luma += streak * 0.6 * (0.5 + 0.5 * hash(float2(line, frame + 5.0)));
    luma += (band + head) * (hash(float2(coord.x * 0.37, line + frame)) - 0.35) * 0.35;
    luma *= 1.0 - scanlines * 0.5 * (0.5 + 0.5 * sin(y * 3.14159265));
    float3 rgb = clamp(toRgb(float3(luma, iq)), 0.0, 1.0);
    return half4(half3(rgb) * alpha, alpha);
}
